// ---------------------------------------------------------------
// TRULY UNIVERSAL BUSINESS INSIGHTS AGGREGATOR (v5 – includes totals)
// Works for any dataset – trips, sales, patients, HR, inventory…
// ---------------------------------------------------------------
const items = $input.all();
if (!items || items.length === 0) return [];

const rows = items.map(i => i.json);
const firstRow = rows[0];

// --- 1. Metadata from Data Cleaning ---
const numericCols = (firstRow._numeric_cols || '').split(',').filter(c => c.trim());
const dateCols    = (firstRow._date_cols   || '').split(',').filter(c => c.trim());
const textColsRaw = (firstRow._text_cols   || '').split(',').filter(c => c.trim());

// --- 2. Choose the best primary metric ---
const businessMetricWords = [
  'revenue', 'amount', 'sales', 'total', 'price', 'value',
  'cost', 'profit', 'income', 'expense',
  'passengers', 'delay', 'duration', 'score', 'rating',
  'quantity', 'qty', 'count', 'volume', 'weight',
  'age', 'salary', 'experience', 'billing'
];
const rowIndexWords = ['row', 'index', 'sno', 'sr', 'no', '#'];

const isRowIndex = col => rowIndexWords.some(w => col.toLowerCase().includes(w));
const isBusinessMetric = col => businessMetricWords.some(w => col.toLowerCase().includes(w));

const nonIndexNumeric = numericCols.filter(c => !isRowIndex(c));
const primaryMetric = nonIndexNumeric.length > 0
  ? (nonIndexNumeric.find(isBusinessMetric) || nonIndexNumeric[0])
  : numericCols[0];

console.log('Primary metric:', primaryMetric);

// --- 3. Group‑by columns (skip IDs, emails, exact personal names) ---
const exactNameCols = ['first_name', 'last_name', 'full_name'];
const groupCols = textColsRaw.filter(col => {
  const lower = col.toLowerCase();
  if (lower.includes('id') || lower.includes('email') || lower.includes('phone')) return false;
  if (exactNameCols.includes(lower)) return false;
  const vals = rows.map(r => r[col]).filter(v => v !== null && v !== undefined && v !== '');
  if (vals.length < 2) return false;
  const uniqueRatio = new Set(vals.map(String)).size / vals.length;
  return uniqueRatio < 0.8;
});

console.log('Group dimensions:', groupCols);

// --- 4. Group statistics (now with total + average) ---
const groupResults = [];
for (const groupCol of groupCols) {
  const groups = {};
  for (const row of rows) {
    const key = row[groupCol];
    if (key === null || key === undefined || key === '') continue;
    const keyStr = String(key);
    if (!groups[keyStr]) {
      groups[keyStr] = { key: keyStr, count: 0 };
      numericCols.forEach(nc => {
        groups[keyStr][nc + '_sum'] = 0;
        groups[keyStr][nc + '_values'] = [];
      });
    }
    groups[keyStr].count++;
    for (const nc of numericCols) {
      const val = row[nc];
      if (typeof val === 'number' && !isNaN(val)) {
        groups[keyStr][nc + '_sum'] += val;
        groups[keyStr][nc + '_values'].push(val);
      }
    }
  }

  const groupArray = Object.values(groups).map(g => {
    const stats = {};
    for (const nc of numericCols) {
      const total = g[nc + '_sum'];
      const count = g[nc + '_values'].length;
      stats[nc] = {
        total: Math.round(total * 100) / 100,
        average: count > 0 ? Math.round((total / count) * 100) / 100 : 0
      };
    }
    return {
      group_column: groupCol,
      group_name: g.key,
      count: g.count,
      metrics: stats
    };
  });

  // Sort by primary metric total descending (or average if total not available)
  const sortKey = primaryMetric ? primaryMetric : numericCols[0];
  groupArray.sort((a, b) => {
    const aVal = a.metrics[sortKey]?.total ?? 0;
    const bVal = b.metrics[sortKey]?.total ?? 0;
    return bVal - aVal;
  });

  groupResults.push({
    dimension: groupCol,
    top_groups: groupArray.slice(0, 5),
    bottom_groups: groupArray.slice(-5),
    total_groups: groupArray.length,
  });
}

// --- 5. Hour distribution ---
let hourAnalysis = null;
if (dateCols.length > 0) {
  const timeCol = dateCols[0];
  const hourCounts = {};
  for (const row of rows) {
    const val = row[timeCol];
    if (val) {
      const d = new Date(val);
      if (!isNaN(d.getTime())) {
        const hour = d.getHours();
        hourCounts[hour] = (hourCounts[hour] || 0) + 1;
      }
    }
  }
  hourAnalysis = hourCounts;
}

// --- 6. Data Quality Summary ---
const qualityIssues = [];
for (const nc of nonIndexNumeric) {
  const negCount = rows.filter(r => typeof r[nc] === 'number' && r[nc] < 0).length;
  if (negCount > 0) qualityIssues.push({ column: nc, issue: `${negCount} negative values found` });
}
for (const nc of nonIndexNumeric) {
  const vals = rows.map(r => Number(r[nc])).filter(v => !isNaN(v));
  if (vals.length > 2) {
    const mean = vals.reduce((a,b)=>a+b,0)/vals.length;
    const max = Math.max(...vals);
    if (mean > 0 && max / mean > 100) qualityIssues.push({ column: nc, issue: `Extreme values (max ${max.toFixed(1)} vs avg ${mean.toFixed(1)}) – possible data error` });
  }
}
let peakHourNote = null;
if (hourAnalysis) {
  const peak = Object.entries(hourAnalysis).sort((a,b) => b[1]-a[1])[0];
  if (peak && peak[0] == 0) peakHourNote = "Peak hour is 0 (midnight) – verify if this is correct or a timestamp/timezone error.";
}

const dataQualitySummary = { issues: qualityIssues, peak_hour_note: peakHourNote };

// --- 7. Overall KPIs (total + average) ---
let totalMetric = 0, metricCount = 0;
if (primaryMetric) {
  for (const r of rows) {
    const v = Number(r[primaryMetric]);
    if (!isNaN(v)) { totalMetric += v; metricCount++; }
  }
}
const avgMetric = metricCount ? totalMetric / metricCount : 0;

const businessInsights = {
  dataset_name: "Automated Data Analysis",
  total_records: rows.length,
  primary_metric: primaryMetric || 'N/A',
  primary_metric_total: Math.round(totalMetric * 100) / 100,
  primary_metric_average: Math.round(avgMetric * 100) / 100,
  peak_hour: hourAnalysis ? Object.entries(hourAnalysis).sort((a,b) => b[1]-a[1])[0]?.[0] : null,
  group_insights: groupResults,
  data_quality: dataQualitySummary,
};

console.log('BUSINESS INSIGHTS:', JSON.stringify(businessInsights, null, 2));

// Attach to every row
items.forEach(item => { item.json.business_insights = businessInsights; });
return items;

// ---------------------------------------------------------------
// UNIVERSAL Data Cleaning – final fix (dedup BEFORE metadata)
// ---------------------------------------------------------------

function normaliseKeys(obj) {
  const newObj = {};
  for (const [key, value] of Object.entries(obj)) {
    const cleanKey = key
      .toLowerCase()
      .replace(/[\s\-]+/g, '_')
      .replace(/[^a-z0-9_]/g, '');
    newObj[cleanKey] = value;
  }
  return newObj;
}

function normalizeNumber(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'string') {
    const cleaned = value.replace(/[^\d.-]/g, '');
    const num = parseFloat(cleaned);
    return isNaN(num) ? null : num;
  }
  return null;
}

function isValidDate(d) {
  if (d instanceof Date && !isNaN(d)) return true;
  if (typeof d === 'string' && !isNaN(Date.parse(d))) return true;
  return false;
}

function normalizeDate(value) {
  try {
    const d = new Date(value);
    if (isNaN(d.getTime())) return null;
    return d.toISOString().split('T')[0];
  } catch { return null; }
}

const inputItems = $input.all();
if (!inputItems || inputItems.length === 0) {
  console.log('DATA CLEANING: No input data.');
  return [];
}

const firstRow = normaliseKeys(inputItems[0].json);
const allKeys = Object.keys(firstRow);

const numericCols = [];
const dateCols = [];
const textCols = [];

for (const key of allKeys) {
  const sampleValues = inputItems.slice(0, 10)
    .map(i => normaliseKeys(i.json)[key])
    .filter(v => v !== null && v !== undefined && v !== '');

  if (sampleValues.length === 0) continue;

  const isIdColumn = key.toLowerCase().includes('id');

  const dateCount = sampleValues.filter(v =>
    typeof v === 'string' && isValidDate(v) && v.length > 5
  ).length;
  const numericCount = sampleValues.filter(v =>
    typeof v === 'number' || (typeof v === 'string' && !isNaN(parseFloat(v.replace(/[^\d.-]/g, ''))))
  ).length;

  if (!isIdColumn && dateCount / sampleValues.length > 0.7) {
    dateCols.push(key);
  } else if (!isIdColumn && numericCount / sampleValues.length > 0.7) {
    numericCols.push(key);
  } else {
    textCols.push(key);
  }
}

console.log('DATA CLEANING: Auto-detected columns:');
console.log('  Numeric:', numericCols);
console.log('  Date:', dateCols);
console.log('  Text:', textCols);

const cleanedItems = [];
const removedItems = [];
const dedupMap = new Map();

for (let i = 0; i < inputItems.length; i++) {
  let raw = normaliseKeys(inputItems[i].json);

  // Convert numeric columns
  for (const col of numericCols) {
    if (raw[col] !== undefined && raw[col] !== null && raw[col] !== '') {
      const num = normalizeNumber(raw[col]);
      raw[col] = num;
    }
  }

  // Normalize date columns
  for (const col of dateCols) {
    if (raw[col] !== undefined && raw[col] !== null && raw[col] !== '') {
      raw[col] = normalizeDate(raw[col]);
    }
  }

  // Trim text columns
  for (const col of textCols) {
    if (typeof raw[col] === 'string') {
      raw[col] = raw[col].trim().replace(/[\u200B-\u200D\uFEFF]/g, '');
      if (raw[col].length > 500) raw[col] = raw[col].substring(0, 500);
    }
  }

  // Skip completely empty rows
  const nonEmptyValues = Object.values(raw).filter(v =>
    v !== null && v !== undefined && v !== ''
  );
  if (nonEmptyValues.length === 0) {
    removedItems.push({ index: i, reason: 'Completely empty row' });
    continue;
  }

  // ---------- DEDUPLICATION (before adding metadata) ----------
  const rowKey = JSON.stringify(raw);
  if (dedupMap.has(rowKey)) {
    removedItems.push({ index: i, reason: 'Exact duplicate row' });
    continue;
  }
  dedupMap.set(rowKey, true);

  // Now add metadata columns
  raw._numeric_cols = numericCols.join(',');
  raw._date_cols = dateCols.join(',');
  raw._text_cols = textCols.join(',');

  cleanedItems.push({ json: raw });
}

console.log('DATA CLEANING SUMMARY:', {
  input: inputItems.length,
  output: cleanedItems.length,
  removed: removedItems.length,
  reasons: removedItems.slice(0, 5).map(r => r.reason)
});

return cleanedItems;

// ---------------------------------------------------------------
// UNIVERSAL Data Transformation – final, with logging
// ---------------------------------------------------------------
const items = $input.all();
if (!items || items.length === 0) {
  console.log('TRANSFORMATION: No input data.');
  return [];
}

const rows = items.map(i => ({ ...i.json }));
const firstRow = rows[0];
const numericCols = (firstRow._numeric_cols || '').split(',').filter(c => c.trim());
const dateCols = (firstRow._date_cols || '').split(',').filter(c => c.trim());

console.log('TRANSFORMATION: All numeric cols:', numericCols);

// --- FILTER: remove any column that contains "id" OR starts with "_year"/"_month" ---
const metricCols = numericCols.filter(col => {
  const lower = col.toLowerCase();
  if (lower.includes('id')) return false;
  if (lower.startsWith('_year') || lower.startsWith('_month')) return false;
  return true;
});

console.log('TRANSFORMATION: Metric columns used for _total:', metricCols);

const output = rows.map((row, idx) => {
  const newRow = { ...row };

  const vals = metricCols
    .map(col => row[col])
    .filter(v => typeof v === 'number' && !isNaN(v));

  if (vals.length > 0) {
    newRow._total = vals.reduce((a, b) => a + b, 0);
    newRow._average = newRow._total / vals.length;
    newRow._min_value = Math.min(...vals);
    newRow._max_value = Math.max(...vals);
    newRow._range = newRow._max_value - newRow._min_value;
  }

  for (const col of dateCols) {
    if (row[col]) {
      try {
        const yr = new Date(row[col]).getFullYear();
        if (!isNaN(yr)) {
          newRow._year = yr;
          newRow._month = new Date(row[col]).getMonth() + 1;
          break;
        }
      } catch (e) {}
    }
  }

  if (row.first_name && row.last_name) {
    newRow.full_name = `${row.first_name} ${row.last_name}`;
  }

  return { json: newRow };
});

console.log(`TRANSFORMATION: Enriched ${output.length} rows.`);
return output;

// ---------------------------------------------------------------
// UNIVERSAL Missing Data Handler — auto-detects all columns
// ---------------------------------------------------------------

function median(arr) {
  if (!arr.length) return null;
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function mode(arr) {
  if (!arr.length) return null;
  const freq = {};
  let maxFreq = 0, modeVal = arr[0];
  for (const val of arr) {
    freq[val] = (freq[val] || 0) + 1;
    if (freq[val] > maxFreq) { maxFreq = freq[val]; modeVal = val; }
  }
  return modeVal;
}

function isMissing(value) {
  return value === null || value === undefined ||
    (typeof value === 'string' && value.trim() === '');
}

const items = $input.all();
const rows = items.map(item => item.json);

if (!rows.length) return [];

// Auto-detect column types from metadata
const numericCols = (rows[0]._numeric_cols || '').split(',').filter(c => c.trim());
const textCols = (rows[0]._text_cols || '').split(',').filter(c => c.trim());

// Build imputation values for numeric columns (use median)
const imputeValues = {};
for (const col of numericCols) {
  const vals = rows
    .map(r => r[col])
    .filter(v => typeof v === 'number' && !isNaN(v));
  if (vals.length > 0) imputeValues[col] = median(vals);
}

// Build imputation values for text columns (use mode)
for (const col of textCols) {
  const vals = rows
    .map(r => r[col])
    .filter(v => typeof v === 'string' && v.trim() !== '');
  if (vals.length > 0) imputeValues[col] = mode(vals);
}

const stats = { imputed: {}, flagged: 0 };
const processedRows = [];

for (const row of rows) {
  const newRow = { ...row };

  // Fill missing numeric columns with median
  for (const col of numericCols) {
    if (isMissing(row[col]) && imputeValues[col] !== undefined) {
      newRow[col] = imputeValues[col];
      stats.imputed[col] = (stats.imputed[col] || 0) + 1;
    }
  }

  // Fill missing text columns with mode
  for (const col of textCols) {
    if (isMissing(row[col]) && imputeValues[col] !== undefined) {
      newRow[col] = imputeValues[col];
      stats.imputed[col] = (stats.imputed[col] || 0) + 1;
    }
  }

  processedRows.push({ json: newRow });
}

console.log('MISSING DATA SUMMARY:', {
  inputCount: rows.length,
  outputCount: processedRows.length,
  imputedCounts: stats.imputed,
  numericColsHandled: numericCols.length,
  textColsHandled: textCols.length,
});

return processedRows;

// ---------------------------------------------------------------
// UNIVERSAL Statistical & Probability Analyzer — fully auto-detecting
// ---------------------------------------------------------------

const items = $input.all();
if (!items || items.length === 0) {
  console.log('STATISTICAL ANALYZER: No input data.');
  return [];
}

console.log(`STATISTICAL ANALYZER: Received ${items.length} items.`);

// Normalize keys (just in case)
const normalizeKeys = obj => {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    out[k.toLowerCase().replace(/[\s\-]+/g, '_').replace(/[^a-z0-9_]/g, '')] = v;
  }
  return out;
};
const rows = items.map(item => normalizeKeys(item.json));

// Auto-detect numeric columns
const numCols = Object.keys(rows[0] || {}).filter(key => typeof rows[0][key] === 'number');
console.log('STATISTICAL ANALYZER: Numeric columns detected:', numCols);

// ---------- Utility functions (same as before) ----------
function welford(values) {
  let count = 0, mean = 0, m2 = 0;
  for (const x of values) { count++; const delta = x - mean; mean += delta / count; const delta2 = x - mean; m2 += delta * delta2; }
  if (count < 2) return { mean, variance: 0, stddev: 0, count };
  const variance = m2 / (count - 1);
  return { mean, variance, stddev: Math.sqrt(variance), count };
}
function median(arr) { if (!arr.length) return null; const s = [...arr].sort((a,b)=>a-b); const m = Math.floor(s.length/2); return s.length%2 ? s[m] : (s[m-1]+s[m])/2; }
function mode(arr) { if (!arr.length) return null; const freq = {}; let mx=0, mv=arr[0]; for (const v of arr) { freq[v]=(freq[v]||0)+1; if(freq[v]>mx){mx=freq[v];mv=v;} } return mv; }
function quantiles(sorted, qs) {
  const n = sorted.length;
  if (n === 0) return {};
  const r = {};
  for (const q of qs) { const pos = (q/100)*(n-1); const lo = Math.floor(pos); const hi = Math.ceil(pos); r[q] = (lo===hi) ? sorted[lo] : sorted[lo] + (pos-lo)*(sorted[hi]-sorted[lo]); }
  return r;
}

const statsReport = {};
const columnData = {};

// For every numeric column, compute statistics and enrich
for (const col of numCols) {
  const vals = rows.map(r => r[col]).filter(v => typeof v === 'number' && !isNaN(v));
  if (!vals.length) { statsReport[col] = { error: 'No valid numeric data' }; continue; }
  columnData[col] = vals;

  const basic = welford(vals);
  const sorted = [...vals].sort((a,b)=>a-b);
  const quants = quantiles(sorted, [0,25,50,75,100]);
  const modeInfo = { value: mode(vals), frequency: 0 };

  statsReport[col] = {
    count: basic.count,
    mean: basic.mean,
    median: quants[50],
    mode: modeInfo.value,
    modeFrequency: 0,
    variance: basic.variance,
    stddev: basic.stddev,
    min: quants[0],
    max: quants[100],
    range: quants[100]-quants[0],
    q1: quants[25],
    q3: quants[75],
    iqr: quants[75]-quants[25],
  };

  // Enrich rows with z‑scores, percentiles, outliers
  const stddev = basic.stddev;
  if (stddev > 0) {
    for (const row of rows) {
      if (typeof row[col] === 'number' && !isNaN(row[col]))
        row[`${col}_zscore`] = (row[col] - basic.mean) / stddev;
    }
  }
  [10,25,50,75,90].forEach(t => {
    const cutoff = sorted[Math.floor(sorted.length*t/100)];
    for (const row of rows) {
      row[`${col}_ge${t}prc`] = (typeof row[col] === 'number' && row[col] >= cutoff) ? 1 : 0;
    }
  });
  const iqr = quants[75] - quants[25];
  const lower = quants[25] - 1.5*iqr;
  const upper = quants[75] + 1.5*iqr;
  for (const row of rows) {
