function pearson(col1, col2) {
  const pairs = rows
    .filter(r => typeof r[col1] === 'number' && !isNaN(r[col1]) &&
                 typeof r[col2] === 'number' && !isNaN(r[col2]));
  if (pairs.length < 2) return 0;
  const a = pairs.map(r => r[col1]);
  const b = pairs.map(r => r[col2]);
  const ma = mean(a), mb = mean(b);
  let num = 0, den1 = 0, den2 = 0;
  for (let i = 0; i < a.length; i++) {
    const da = a[i] - ma, db = b[i] - mb;
    num += da * db;
    den1 += da * da;
    den2 += db * db;
  }
  const den = Math.sqrt(den1 * den2);
  return den === 0 ? 0 : Math.round((num / den) * 1000) / 1000;
}

