const slope = (n * sumXY - sumX * sumY) / denominator;
const intercept = (sumY - slope * sumX) / n;
const r2Denom = Math.sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));
const r2 = r2Denom === 0 ? 0 : Math.pow((n * sumXY - sumX * sumY) / r2Denom, 2);

