}

console.log('CLUSTERING: Using features:', features);

const k = Math.min(3, Math.floor(rows.length / 3));
if (k < 2) {
  return rows.map(row => ({ json: { ...row, cluster: 0 } }));
}

const points = rows
  .map(r => features.map(f => r[f]))
  .filter(p => p.every(v => typeof v === 'number' && !isNaN(v)));

if (points.length < k) return items;

// Normalize points for better clustering
const mins = features.map((_, d) => Math.min(...points.map(p => p[d])));
const maxs = features.map((_, d) => Math.max(...points.map(p => p[d])));
const normalize = p => p.map((v, d) => maxs[d] === mins[d] ? 0 : (v - mins[d]) / (maxs[d] - mins[d]));
const normPoints = points.map(normalize);

// K-means
const centroids = normPoints.slice(0, k).map(p => [...p]);
let assignments = new Array(normPoints.length).fill(0);
let changed = true;
let iterations = 0;

while (changed && iterations < 100) {
  changed = false;
  iterations++;

  for (let i = 0; i < normPoints.length; i++) {
    let minDist = Infinity, minIdx = 0;
    for (let c = 0; c < k; c++) {
      const dist = normPoints[i].reduce((sum, val, d) => sum + (val - centroids[c][d]) ** 2, 0);
      if (dist < minDist) { minDist = dist; minIdx = c; }
    }
    if (assignments[i] !== minIdx) { assignments[i] = minIdx; changed = true; }
  }

  const sums = Array(k).fill(0).map(() => new Array(features.length).fill(0));
  const counts = Array(k).fill(0);
  for (let i = 0; i < normPoints.length; i++) {
    counts[assignments[i]]++;
    for (let d = 0; d < features.length; d++) sums[assignments[i]][d] += normPoints[i][d];
  }
  for (let c = 0; c < k; c++) {
    if (counts[c] > 0) {
      for (let d = 0; d < features.length; d++) centroids[c][d] = sums[c][d] / counts[c];
    }
  }
}

let pointIdx = 0;
