// ---------- Universal rule generators ----------

// 1. Email columns: if the column name contains 'email', apply email regex
function isEmailLike(colName) {
  return colName.toLowerCase().includes('email') || colName.toLowerCase().includes('e_mail');
}

// 2. Phone columns: if column name contains 'phone' or 'mobile'
function isPhoneLike(colName) {
  const lower = colName.toLowerCase();
  return lower.includes('phone') || lower.includes('mobile') || lower.includes('contact');
}

// 3. For numeric columns: flag extreme outliers (>5 standard deviations from mean)
function computeNumericStats(values) {
  if (values.length < 3) return null;
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
  const stddev = Math.sqrt(variance);
  return { mean, stddev };
}

// 4. For date columns: flag dates outside the range 1900-01-01 to 2100-12-31
function isValidBusinessDate(val) {
  if (!val) return true; // missing values are handled separately by the Missing Data Handler
  const d = new Date(val);
  if (isNaN(d.getTime())) return false;
  const year = d.getFullYear();
  return year >= 1900 && year <= 2100;
}

// ---------- Build dynamic rules ----------
const dynamicRules = [];

// Numeric rules (extreme outlier detection)
const numericStats = {};
for (const col of numericCols) {
  const vals = rows.map(r => r[col]).filter(v => typeof v === 'number' && !isNaN(v));
  const stats = computeNumericStats(vals);
  if (stats && stats.stddev > 0) {
    numericStats[col] = stats;
    // We'll check each row's z‑score later
  }
}

// Date rules
for (const col of dateCols) {
  dynamicRules.push({
    field: col,
    type: 'date',
    validate: (val) => isValidBusinessDate(val),
    message: `Date outside reasonable range (1900‑2100)`,
  });
}

// Text rules
for (const col of textCols) {
  if (isEmailLike(col)) {
    dynamicRules.push({
      field: col,
      type: 'email',
      validate: (val) => {
        if (typeof val !== 'string') return true;
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim());
      },
      message: `Invalid email format`,
    });
  } else if (isPhoneLike(col)) {
    dynamicRules.push({
      field: col,
      type: 'phone',
      validate: (val) => {
        if (typeof val !== 'string') return true;
        // Simple check: at least 7 digits after removing non‑digit characters
        const digits = val.replace(/\D/g, '');
        return digits.length >= 7;
      },
      message: `Invalid phone number (fewer than 7 digits)`,
    });
  }
  // For other text columns we could flag very long strings, but that's optional
}

// ---------- Apply validation row by row ----------
const validationErrors = [];

