function exponentialSmoothing(values, alpha = 0.5) {
  if (values.length < 2) return null;
  let forecast = values[0];
  for (let i = 1; i < values.length; i++) {
    forecast = alpha * values[i] + (1 - alpha) * forecast;
  }
  return forecast;
}

