    if (i >= 2) {
      const windowVals = sortedRows.slice(i-2, i+1).map(r => r[col]).filter(v => typeof v === 'number');
      if (windowVals.length === 3) {
        const sma = windowVals.reduce((s, v) => s + v, 0) / 3;
        sortedRows[i][`${col}_sma3`] = Math.round(sma * 100) / 100;
