        .filter(p => Number.isFinite(p.y));
    }
    return [];
  })().slice(-80);

  const avgByCol = numericCols.slice(0, 12).map(col => {
    const vals = rows.map(r => Number(r[col])).filter(v => Number.isFinite(v));
    return {
      col,
      avg: vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0
    };
  });

  const hist = buildHistogram(amountValues);
  const cat = buildFrequency(categoryCol, 12);

  const rowsJson = JSON.stringify(rows).replace(/</g, '\\u003c');
  const colsJson = JSON.stringify(visibleCols).replace(/</g, '\\u003c');
  const riskJson = JSON.stringify({
    High: highRiskCount,
    Medium: mediumRiskCount,
    Low: lowRiskCount,
    Unknown: rows.length - highRiskCount - mediumRiskCount - lowRiskCount
  }).replace(/</g, '\\u003c');
  const histJson = JSON.stringify(hist).replace(/</g, '\\u003c');
  const catJson = JSON.stringify(cat).replace(/</g, '\\u003c');
  const trendJson = JSON.stringify(trendPoints).replace(/</g, '\\u003c');
  const avgJson = JSON.stringify(avgByCol).replace(/</g, '\\u003c');
  const amountColJson = JSON.stringify(amountCol).replace(/</g, '\\u003c');
  const categoryColJson = JSON.stringify(categoryCol).replace(/</g, '\\u003c');
  const dateColJson = JSON.stringify(dateCol).replace(/</g, '\\u003c');
  const numericColsJson = JSON.stringify(numericCols).replace(/</g, '\\u003c');
  const clusterExistsJson = JSON.stringify(clusterExists).replace(/</g, '\\u003c');
  const clusterValuesJson = JSON.stringify(clusterValues).replace(/</g, '\\u003c');

  const defaultPageSize = rows.length <= 500 ? 'all' : 100;

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Executive Dashboard</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
  :root{
    --bg:#020617;
    --panel:rgba(15,23,42,.90);
    --panel2:rgba(17,24,39,.94);
    --line:rgba(148,163,184,.16);
    --text:#e5e7eb;
    --muted:#94a3b8;
    --accent:#60a5fa;
    --good:#34d399;
    --warn:#fbbf24;
    --bad:#fb7185;
    --shadow:0 28px 90px rgba(0,0,0,.42);
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:
      radial-gradient(circle at top left, rgba(96,165,250,.16), transparent 28%),
      radial-gradient(circle at top right, rgba(52,211,153,.10), transparent 22%),
      linear-gradient(180deg, #020617 0%, #050b1a 55%, #020617 100%);
    color:var(--text);
    font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
  }
