    cursor:pointer;
    transition:.2s ease;
  }
  .btn:hover{transform:translateY(-1px);background:rgba(255,255,255,.09)}
  .btn:disabled{opacity:.45;cursor:not-allowed;transform:none}
  .table-scroll{
    overflow:auto;
    max-height:72vh;
    border-radius:18px;
    border:1px solid var(--line);
    background:rgba(2,6,23,.56);
  }
  table{
    width:100%;
    border-collapse:collapse;
    min-width:1100px;
