    letter-spacing:.10em;
    text-transform:uppercase;
    padding:12px 12px;
    border-bottom:1px solid var(--line);
  }
  tbody td{
    padding:11px 12px;
    border-bottom:1px solid rgba(148,163,184,.10);
    color:#e2e8f0;
    font-size:13px;
    white-space:nowrap;
  }
  tbody tr:hover td{background:rgba(96,165,250,.08)}
  .badge{
    display:inline-flex;
    align-items:center;
    gap:6px;
    padding:4px 10px;
    border-radius:999px;
    border:1px solid var(--line);
    font-size:12px;
  }
  .high{background:rgba(251,113,133,.14); color:#fecdd3}
  .med{background:rgba(251,191,36,.14); color:#fde68a}
  .low{background:rgba(52,211,153,.14); color:#bbf7d0}
  .cluster{
    background:rgba(96,165,250,.12);
    color:#dbeafe;
  }
  .empty{
    padding:22px;
    color:#94a3b8;
    text-align:center;
  }
  .pager{
    display:flex;
    gap:10px;
    flex-wrap:wrap;
    align-items:center;
    justify-content:flex-end;
    margin-top:12px;
  }
  .pager .btn{
    padding:8px 12px;
    border-radius:12px;
  }
  .pager .pageinfo{
    color:#cbd5e1;
    font-size:13px;
    padding:8px 12px;
    border:1px solid var(--line);
    border-radius:12px;
    background:rgba(255,255,255,.04);
  }
  .footer{
    padding:16px 28px 24px;
    color:var(--muted);
    font-size:12px;
    text-align:center;
  }
  @media (max-width: 1200px){
    .controls,.subcontrols,.kpis,.grid{grid-template-columns:1fr 1fr}
  }
  @media (max-width: 760px){
    .page{width:min(100% - 14px, 1520px)}
    .hero,.content,.kpis{padding-left:16px;padding-right:16px}
    .controls,.subcontrols,.kpis,.grid{grid-template-columns:1fr}
  }
</style>
</head>
<body>
  <div class="page">
    <div class="shell">
      <div class="hero">
        <div class="hero-top">
          <div>
            <h1>📊 Executive Trust Dashboard</h1>
            <div class="sub">A centered, luxury-style dashboard with full-row search, cluster visibility, pagination, sorting, and one-click export.</div>
          </div>
          <div class="pill-row">
            <div class="pill">Records: ${rows.length}</div>
            <div class="pill">Columns: ${visibleCols.length}</div>
            <div class="pill">Numeric: ${numericCols.length}</div>
            <div class="pill">Anomalies: ${anomalyCount}</div>
          </div>
        </div>

        <div class="controls">
          <input id="searchBox" class="input" type="text" placeholder="Search any value in any column..." />
          <select id="columnFilter" class="select">
            <option value="">All columns</option>
            ${visibleCols.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('')}
          </select>
          <select id="riskFilter" class="select">
            <option value="">All risk levels</option>
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
            <option value="Unknown">Unknown</option>
          </select>
          <select id="clusterFilter" class="select" ${clusterExists ? '' : 'disabled'}>
            <option value="">All clusters</option>
            ${clusterValues.map(c => `<option value="${escapeHtml(c)}">Cluster ${escapeHtml(c)}</option>`).join('')}
          </select>
        </div>

        <div class="subcontrols">
          <select id="sortField" class="select">
            <option value="">Sort by default</option>
            ${visibleCols.map(c => `<option value="${escapeHtml(c)}"${c === amountCol ? ' selected' : ''}>${escapeHtml(c)}</option>`).join('')}
          </select>
          <select id="sortDirection" class="select">
            <option value="desc">Descending</option>
            <option value="asc">Ascending</option>
          </select>
          <select id="pageSize" class="select">
            <option value="25">25 rows</option>
            <option value="50">50 rows</option>
            <option value="100">100 rows</option>
            <option value="250">250 rows</option>
            <option value="500">500 rows</option>
            <option value="all">All rows</option>
          </select>
          <button class="btn" id="downloadCsvBtn">Download CSV</button>
        </div>
      </div>

      <div class="kpis">
        <div class="kpi">
          <div class="label">Total records</div>
          <div class="value" id="kpiRows">0</div>
          <div class="note">All rows are searchable</div>
        </div>
        <div class="kpi">
          <div class="label">Total value</div>
          <div class="value" id="kpiTotal">$0</div>
          <div class="note">${amountCol ? escapeHtml(amountCol) : 'No amount-like column found'}</div>
        </div>
        <div class="kpi">
          <div class="label">Average value</div>
          <div class="value" id="kpiAvg">$0</div>
          <div class="note">Based on the selected numeric metric</div>
        </div>
        <div class="kpi">
          <div class="label">Clusters detected</div>
          <div class="value" id="kpiCluster">${clusterValues.length || (clusterExists ? 1 : 0)}</div>
          <div class="note">Cluster field is shown in the table</div>
        </div>
      </div>

      <div class="content">
        <div class="grid">
          <div class="card">
            <h3>${amountCol ? escapeHtml(amountCol) : 'Value'} distribution</h3>
            <div class="chart"><canvas id="histChart"></canvas></div>
          </div>
          <div class="card">
            <h3>${categoryCol ? escapeHtml(categoryCol) : 'Category'} breakdown</h3>
            <div class="chart"><canvas id="catChart"></canvas></div>
          </div>
        </div>

        <div class="card" style="margin-bottom:14px">
          <h3>Trend preview</h3>
          <div class="chart tall"><canvas id="trendChart"></canvas></div>
        </div>

        <div class="grid">
          <div class="card">
            <h3>Risk levels</h3>
            <div class="chart"><canvas id="riskChart"></canvas></div>
          </div>
          <div class="card">
            <h3>Average by numeric column</h3>
            <div class="chart"><canvas id="avgChart"></canvas></div>
          </div>
        </div>

        <div class="card table-card">
          <div class="table-head">
            <h3 style="margin:0">Full data table</h3>
            <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">
              <div class="small"><span id="matchedCount">${rows.length}</span> matched of <span id="totalCount">${rows.length}</span></div>
              <div class="small" id="pageInfo"></div>
            </div>
          </div>
          <div class="table-scroll">
            <table>
              <thead>
                <tr id="tableHead"></tr>
              </thead>
              <tbody id="tableBody"></tbody>
            </table>
          </div>
          <div class="pager" id="pager"></div>
        </div>

        <div class="footer">Generated automatically · ${new Date().toLocaleString()}</div>
      </div>
    </div>
  </div>

<script>
  const ROWS = ${rowsJson};
  const COLS = ${colsJson};
  const RISK = ${riskJson};
  const HIST = ${histJson};
  const CAT = ${catJson};
  const TREND = ${trendJson};
  const AVG = ${avgJson};
  const AMOUNT_COL = ${amountColJson};
  const CATEGORY_COL = ${categoryColJson};
  const DATE_COL = ${dateColJson};
  const NUMERIC_COLS = ${numericColsJson};
  const CLUSTER_EXISTS = ${clusterExistsJson};
  const CLUSTER_VALUES = ${clusterValuesJson};
  const DEFAULT_PAGE_SIZE = ${JSON.stringify(defaultPageSize)};

  const searchBox = document.getElementById('searchBox');
  const columnFilter = document.getElementById('columnFilter');
  const riskFilter = document.getElementById('riskFilter');
  const clusterFilter = document.getElementById('clusterFilter');
  const sortField = document.getElementById('sortField');
  const sortDirection = document.getElementById('sortDirection');
  const pageSizeEl = document.getElementById('pageSize');
  const tableHead = document.getElementById('tableHead');
  const tableBody = document.getElementById('tableBody');
  const matchedCount = document.getElementById('matchedCount');
  const pageInfo = document.getElementById('pageInfo');
  const pager = document.getElementById('pager');

  if (DEFAULT_PAGE_SIZE === 'all') {
    pageSizeEl.value = 'all';
  } else {
    pageSizeEl.value = String(DEFAULT_PAGE_SIZE);
  }

  const fmt = (n) => {
    const num = Number(n);
    if (!Number.isFinite(num)) return '—';
    return new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(num);
  };

  const money = (n) => {
    const num = Number(n);
    if (!Number.isFinite(num)) return '$0';
    return '$' + new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(num);
  };

  const esc = (v) => String(v ?? '')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#39;');

  let currentPage = 1;

  function animateCount(el, target, prefix = '', suffix = '') {
    let current = 0;
    const step = Math.max(1, Math.ceil(target / 60));
    const timer = setInterval(() => {
      current = Math.min(target, current + step);
      el.textContent = prefix + fmt(current) + suffix;
      if (current >= target) clearInterval(timer);
    }, 16);
  }

  function buildHeader() {
    tableHead.innerHTML = COLS.map(c => '<th>' + esc(c) + '</th>').join('');
  }

  function isNumericValue(v) {
    return typeof v === 'number' && Number.isFinite(v);
  }

  function compareValues(a, b, col) {
    const av = a[col];
    const bv = b[col];

    if (isNumericValue(av) && isNumericValue(bv)) return av - bv;

    const ad = av ? new Date(av) : null;
    const bd = bv ? new Date(bv) : null;
    if (ad && bd && !isNaN(ad.getTime()) && !isNaN(bd.getTime())) {
      return ad.getTime() - bd.getTime();
    }

    return String(av ?? '').localeCompare(String(bv ?? ''), undefined, { numeric: true, sensitivity: 'base' });
  }

  function matchesFilters(row, q, selectedCol, selectedRisk, selectedCluster) {
    if (selectedRisk && String(row.risk_level || 'Unknown') !== selectedRisk) return false;

    if (selectedCluster !== '') {
      const clusterVal = row.cluster === null || row.cluster === undefined ? '' : String(row.cluster);
      if (clusterVal !== selectedCluster) return false;
    }

    if (!q) return true;

    if (selectedCol) {
      return String(row[selectedCol] ?? '').toLowerCase().includes(q);
    }

    return COLS.some(c => String(row[c] ?? '').toLowerCase().includes(q));
  }

  function getFilteredRows() {
    const q = searchBox.value.trim().toLowerCase();
    const selectedCol = columnFilter.value;
    const selectedRisk = riskFilter.value;
    const selectedCluster = clusterFilter ? clusterFilter.value : '';

    const filtered = ROWS.filter(r => matchesFilters(r, q, selectedCol, selectedRisk, selectedCluster));

    const sortCol = sortField.value;
    const sortDir = sortDirection.value === 'asc' ? 1 : -1;
    if (sortCol) {
      filtered.sort((a, b) => compareValues(a, b, sortCol) * sortDir);
    }
    return filtered;
  }

  function getPageSize() {
    return pageSizeEl.value === 'all' ? 'all' : Math.max(1, Number(pageSizeEl.value) || 25);
  }

  function renderPager(totalRows, pageSize) {
    pager.innerHTML = '';

    if (pageSize === 'all' || totalRows <= pageSize) {
      pageInfo.textContent = totalRows ? 'Showing all matched rows' : 'No rows matched';
      return;
    }

    const totalPages = Math.max(1, Math.ceil(totalRows / pageSize));
    if (currentPage > totalPages) currentPage = totalPages;

    const prev = document.createElement('button');
    prev.className = 'btn';
    prev.textContent = 'Prev';
    prev.disabled = currentPage <= 1;
    prev.onclick = () => { currentPage = Math.max(1, currentPage - 1); render(); };

    const next = document.createElement('button');
    next.className = 'btn';
    next.textContent = 'Next';
    next.disabled = currentPage >= totalPages;
    next.onclick = () => { currentPage = Math.min(totalPages, currentPage + 1); render(); };

    const info = document.createElement('span');
    info.className = 'pageinfo';
    info.textContent = 'Page ' + currentPage + ' / ' + totalPages;

    pager.appendChild(prev);
    pager.appendChild(info);
    pager.appendChild(next);

    const start = ((currentPage - 1) * pageSize) + 1;
    const end = Math.min(totalRows, currentPage * pageSize);
    pageInfo.textContent = 'Rows ' + start + '–' + end + ' of ' + totalRows;
  }

  function renderTable(rows) {
    const pageSize = getPageSize();

    if (!rows.length) {
      tableBody.innerHTML = '<tr><td class="empty" colspan="' + COLS.length + '">No rows match the current filters.</td></tr>';
      matchedCount.textContent = '0';
      pageInfo.textContent = 'No rows matched';
      pager.innerHTML = '';
      return;
    }

    let pageRows = rows;
    if (pageSize !== 'all') {
      const start = (currentPage - 1) * pageSize;
      pageRows = rows.slice(start, start + pageSize);
    }

    tableBody.innerHTML = pageRows.map(row => {
      const cells = COLS.map(col => {
        const v = row[col];

        if (col === 'risk_level') {
          const cls = v === 'High' ? 'high' : v === 'Medium' ? 'med' : 'low';
          const label = v || 'Unknown';
          return '<td><span class="badge ' + cls + '">' + esc(label) + '</span></td>';
        }

        if (col === 'cluster') {
          return '<td><span class="badge cluster">Cluster ' + esc(v) + '</span></td>';
        }

        if (typeof v === 'number') return '<td>' + fmt(v) + '</td>';
        if (v === null || v === undefined || v === '') return '<td style="color:#64748b">—</td>';
        return '<td>' + esc(v) + '</td>';
      }).join('');

      return '<tr>' + cells + '</tr>';
    }).join('');

    matchedCount.textContent = String(rows.length);
    renderPager(rows.length, pageSize);
  }

  function exportCsv(rows) {
    const header = COLS.join(',');
    const body = rows.map(r => COLS.map(c => {
      const text = r[c] === null || r[c] === undefined ? '' : String(r[c]);
      return '"' + text.replace(/"/g, '""') + '"';
    }).join(','));
    return [header].concat(body).join('\\n');
  }

  function downloadTextFile(filename, text) {
    const blob = new Blob([text], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  function renderCharts() {
    if (typeof Chart === 'undefined') return;

    const chartTheme = {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 1100, easing: 'easeOutQuart' },
      plugins: {
        legend: { labels: { color: '#cbd5e1' } },
        tooltip: {
          backgroundColor: '#0f172a',
          borderColor: 'rgba(148,163,184,.20)',
          borderWidth: 1,
          titleColor: '#fff',
          bodyColor: '#cbd5e1'
        }
      },
      scales: {
        x: { ticks: { color: '#94a3b8' }, grid: { color: 'rgba(148,163,184,.08)' } },
        y: { ticks: { color: '#94a3b8' }, grid: { color: 'rgba(148,163,184,.08)' } }
      }
    };

    new Chart(document.getElementById('histChart'), {
      type: 'bar',
      data: {
        labels: HIST.labels,
        datasets: [{
          label: AMOUNT_COL || 'Count',
          data: HIST.data,
          borderRadius: 8
        }]
      },
      options: { ...chartTheme, plugins: { ...chartTheme.plugins, legend: { display: false } } }
    });

    new Chart(document.getElementById('catChart'), {
      type: 'bar',
      data: {
        labels: CAT.labels,
        datasets: [{
          label: 'Count',
          data: CAT.data,
          borderRadius: 8
        }]
      },
      options: { ...chartTheme, indexAxis: 'y', plugins: { ...chartTheme.plugins, legend: { display: false } } }
    });

    const trendLabels = TREND.map(p => String(p.x).slice(0, 10));
    const trendValues = TREND.map(p => p.y);

    new Chart(document.getElementById('trendChart'), {
      type: 'line',
      data: {
        labels: trendLabels,
        datasets: [{
          label: AMOUNT_COL || 'Value',
          data: trendValues,
          tension: 0.32,
          fill: true
        }]
      },
      options: { ...chartTheme, plugins: { ...chartTheme.plugins, legend: { display: false } } }
    });

    new Chart(document.getElementById('riskChart'), {
      type: 'doughnut',
      data: {
        labels: Object.keys(RISK),
        datasets: [{ data: Object.values(RISK) }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom', labels: { color: '#cbd5e1' } } }
      }
    });

    const avgLabels = AVG.map(x => x.col);
    const avgData = AVG.map(x => Math.round(x.avg * 100) / 100);

    new Chart(document.getElementById('avgChart'), {
      type: 'bar',
      data: {
        labels: avgLabels.map(x => x.replace(/_/g, ' ')),
        datasets: [{
          label: 'Average',
          data: avgData,
          borderRadius: 8
        }]
      },
      options: {
        ...chartTheme,
        plugins: { ...chartTheme.plugins, legend: { display: false } }
      }
    });
  }

  function render() {
    const filtered = getFilteredRows();
    renderTable(filtered);
  }

  buildHeader();

  const refresh = () => { currentPage = 1; render(); };

  searchBox.addEventListener('input', refresh);
  columnFilter.addEventListener('change', refresh);
  riskFilter.addEventListener('change', refresh);
  if (clusterFilter) clusterFilter.addEventListener('change', refresh);
  sortField.addEventListener('change', refresh);
  sortDirection.addEventListener('change', refresh);
  pageSizeEl.addEventListener('change', refresh);

  document.getElementById('downloadCsvBtn').addEventListener('click', () => {
    const filtered = getFilteredRows();
    downloadTextFile('executive_dashboard_filtered.csv', exportCsv(filtered));
  });

  animateCount(document.getElementById('kpiRows'), ROWS.length);
  animateCount(document.getElementById('kpiTotal'), Math.round(${totalValue}), '');
  animateCount(document.getElementById('kpiAvg'), Math.round(${avgValue}), '');
  animateCount(document.getElementById('kpiCluster'), ${clusterValues.length || (clusterExists ? 1 : 0)});

  renderCharts();
  render();
</script>
</body>
</html>`;

  return [{
    json: {
      data: html,
      mimeType: 'text/html',
      fileName: 'executive_dashboard.html'
    }
  }];

} catch (e) {
  return [{
    json: {
      data: `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8" />
<title>Dashboard Error</title>
<style>
