// ---------------------------------------------------------------
// Build HTML File — correctly converts HTML string to binary
// Place this INSTEAD of Convert to File node
// ---------------------------------------------------------------

const item = $input.first().json;

// Get the HTML content
const htmlContent = item.data || item.html || '';

if (!htmlContent) {
  return [{ json: { error: 'No HTML content found' } }];
}

// Convert HTML string to binary buffer
const buffer = Buffer.from(htmlContent, 'utf-8');

return [{
  json: { fileName: 'analysis_report.html' },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'analysis_report.html',
      fileExtension: 'html',
    }
  }
}];
